function canDo(grants, role, action) {
  const allowed = grants[role];
  if (!Array.isArray(allowed)) return false;
  return allowed.includes(action);
}

function withinLimit(bytes, maxBytes) {
  return Number.isInteger(bytes) && bytes > 0 && bytes <= maxBytes;
}

function isFresh(issuedAt, now, ttlSeconds) {
  const age = now - issuedAt;
  return age >= 0 && age < ttlSeconds;
}

function isAllowedExtension(filename, allowed) {
  const dot = filename.lastIndexOf(".");
  if (dot === -1) return false;
  return allowed.includes(filename.slice(dot).toLowerCase());
}

