function isUploadAllowed(filename, sizeBytes, allowed, maxBytes) {
  const dot = filename.lastIndexOf(".");
  if (dot <= 0) return false;
  const extension = filename.slice(dot).toLowerCase();
  if (!allowed.includes(extension)) return false;
  return Number.isInteger(sizeBytes) && sizeBytes >= 1 && sizeBytes <= maxBytes;
}

function canAccess(policy, role, action) {
  const rules = policy[role];
  if (!rules) return false;
  const allow = rules.allow || [];
  const deny = rules.deny || [];
  if (deny.includes(action)) return false;
  return allow.includes(action);
}

function isLinkValid(link, now, objectKey) {
  if (!link) return false;
  if (link.key !== objectKey) return false;
  if (typeof now !== "number" || typeof link.expiresAt !== "number") return false;
  return now < link.expiresAt;
}
